with open('/home/user/workspace/13511660557912876654/buddhist-ontology/data/modern-translation/t1957.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

ts = data['translations']

# 正确逐段翻译
ts[0]['modern'] = "【安乐净土所属界分问答】【义解】释昙鸾撰。有人问：「安乐净土在三界中，属于哪一界摄持呢？」回答说：「如《大智度论》所说：『这样的净土，不是三界所摄持的。』为什么呢？因为净土没有欲染，所以不是欲界；是地居的净土，所以不是色界；众生有形色相好可见，所以不是无色界。经上说：『阿弥陀佛过去行菩萨道的时候，作比丘，名叫法藏。"
ts[1]['modern'] = "【法藏菩萨发愿成佛】【义解】在世自在王佛那里，请问诸佛净土的行法，当时世自在王佛为他宣说二百一十亿诸佛刹土，天人的善恶、国土的精粗，都显现给他看。那时候法藏菩萨，就在佛前发弘誓大愿，摄取诸佛国土的清净功德。」经过无量阿僧祇劫，依照所发的大愿修行诸波罗蜜，万善圆满，成就无上佛道。"
ts[2]['modern'] = "【别业净土非三界摄，净土庄严分科】【义解】这是阿弥陀佛别业所成就的净土，不属于三界。」问：「安乐国有多少种庄严，才称为净土呢？」回答说：「如果依照经文依据义理，法藏菩萨的四十八愿就是其事，看《往生论赞》就可以知道，不再重复叙述。如果依照《无量寿论》（即《往生论》），用两种清净，总摄二十九种庄严成就。两种清净是：一器世间清净，二是众生世间清净。"
ts[3]['modern'] = "【器世间庄严开端：第一至第四】【义解】器世间清净，有十七种庄严成就：第一，国土相状胜过三界道；第二，国土广大，其量如同虚空，没有边界限量；第三，从菩萨正道大慈悲出世善根所生起；第四，清净光明圆满庄严。"
ts[4]['modern'] = "【器世间庄严第五至第八】【义解】第五，具足第一等珍宝性，出生奇妙的宝物；第六，洁净光明常照世间；第七，国土的宝物性质柔软，接触到的人都舒适悦乐，生起殊胜的快乐；第八，千万种宝华庄严池沼，宝殿、宝楼阁、种种宝树，杂色光明影纳十方世界，无量宝网覆盖虚空，四面悬挂宝铃，常宣说妙法音声。"
ts[5]['modern'] = "【器世间庄严第九至第十四】【义解】第九，在虚空中自然常雨天华、天衣、天香，普遍庄严熏染国土；第十，佛的智慧光明普照，照除众生的愚痴黑暗；第十一，清净梵音开悟众生，远闻十方世界；第十二，阿弥陀佛是无上法王，以善力住持国土；第十三，净土众生都是从如来净华中化生；第十四，众生爱乐佛法法味，以禅三昧为食。"
ts[6]['modern'] = "【器世间庄严第十五至第十七，众生世间清净开端】【义解】第十五，永远远离身心各种痛苦，受乐没有间断；第十六，乃至听不到二乘、女人、根缺的名称；第十七，众生有所欲乐，随心意都能满足，没有不称意的。以上这十七种，就叫器世间清净。众生世间清净，有十二种庄严成就：第一，无量大珍宝王微妙华台，作为佛的宝座。"
ts[7]['modern'] = "【众生世间庄严：佛功德一至五】【义解】第二，无量相好、无量光明庄严佛身；第三，佛有无量辩才，应机说法，言辞清白具足，令人乐闻，听到的人必定悟解，所说的言教真实不虚；第四，佛的真如智慧如同虚空，照了诸法总相别相，心没有分别；第五，天人圣众不动聚会，广大庄严，"
ts[8]['modern'] = "【众生世间庄严：佛功德六至八】【义解】就像须弥山映显四大海，法王相好圆满具足；第六，成就无上佛果，尚且没有能比得上的，何况有超过的；第七，佛是人天丈夫、调御师，受大众恭敬围绕，如同狮子王被狮子围绕；第八，以佛本愿力庄严、住持一切功德，遇到佛的人都不会空过，能让众生迅速满足一切功德海。"
ts[9]['modern'] = "【众生世间庄严：菩萨功德九至十】【义解】还没有证得净心的菩萨，毕竟能证得平等法身，和净心菩萨、上地菩萨毕竟同证寂灭平等；第九，安乐国的菩萨大众，身不动摇就能遍至十方世界，种种应化，如实修行，常作佛事；第十，这些菩萨的应化身，在一切时不前不后，一心一念放大光明，都能遍至十方世界教化众生，以种种方便修行成就，灭除一切众生的苦恼。"
ts[10]['modern'] = "【众生世间庄严：菩萨功德十一至十二，总结】【义解】第十一，这些菩萨在一切世界无有剩余，照见诸佛大会无有剩余，以广大无量的供养、恭敬、赞叹诸佛如来功德；第十二，这些菩萨在十方一切没有三宝的地方，住持、庄严佛、法、僧三宝功德大海，普遍开示让众生解了，如实修行。以上是法王八种庄严功德成就，菩萨四种庄严功德成就，这就叫众生世间清净。"
ts[11]['modern'] = "【往生辈品分科】【义解】安乐国土具备以上这二十九种庄严功德成就，所以叫净土。」问：「往生安乐净土的人，一共有几品几辈？有几种因缘呢？」回答说：「《无量寿经》里只有三辈：上辈、中辈、下辈；《无量寿观经》（即《观无量寿佛经》）里，每一品又分为上、中、下，三三成九，合为九品。现在依傍《无量寿经》作赞，暂且根据这部经作三品来说。"
ts[12]['modern'] = "【上辈往生因缘】【义解】上辈往生的人，有五种因缘：第一，舍家离欲，作沙门；第二，发无上菩提心；第三，一向专念无量寿佛；第四，修行各种功德；第五，发愿往生安乐国。具备这些因缘，临命终的时候，无量寿佛和诸大菩萨圣众显现在这个人面前，这个人就随佛往生安乐国，在七宝华中自然化生，住不退转地，智慧勇猛，神通自在。"
ts[13]['modern'] = "【中辈往生因缘】【义解】中辈往生的人，有七种因缘：第一，发无上菩提心；第二，一向专念无量寿佛；第三，或多或少修善，奉持斋戒；第四，起立塔像；第五，饭食沙门；第六，悬缯燃灯，散华烧香；第七，把这些功德回向发愿往生安乐国。临命终的时候，无量寿佛化现其身，光明相好和真佛一样，和诸大菩萨圣众显现在这个人面前，这个人就随化佛往生安乐国，住不退转地，功德智慧仅次于上辈往生的人。"
ts[14]['modern'] = "【下辈往生因缘，边地胎生缘起】【义解】下辈往生的人，有三种因缘：第一，如果不能作各种功德，也应当发无上菩提心；第二，一向专意，乃至十念念无量寿佛；第三，以至诚心发愿往生安乐国。临命终的时候，梦见无量寿佛，也得以往生，功德智慧仅次于中辈往生的人。又有一种往生安乐国的情况，不在三辈当中：就是以疑惑心修各种功德，愿生安乐国，不能了知佛智、不思议智、不可称智、大乘广智、无等无伦最上胜智，对于这些智慧疑惑不信，但还是相信罪福因果，修习善本，往生安乐国。"
ts[15]['modern'] = "【边地胎生果报】【义解】往生到安乐国的七宝宫殿，宫殿有的大百由旬，有的大五百由旬，各人在里面享受各种快乐，如同忉利天人一样，也都是自然而有。但在五百年当中，常常不见佛，不闻经法，不见菩萨、声闻圣众。安乐国土把这叫做边地，也叫胎生。"
ts[16]['modern'] = "【边地胎生释义】【义解】叫边地，是说五百年中不见闻三宝，义理如同边地的难处；也因为他们在安乐国土最边缘的地方。叫胎生，譬如胎生的人刚生下来的时候，人法还没有成就。边是说它的难处，胎是说它的暗昧，这两个名称都是借这个比喻那个，不是八难中的边地，也不是胞胎里的胎生。怎么知道呢？因为安乐国土一向都是化生，所以知道不是实胎生；五百年之后还得以见闻三宝，所以知道不是八难中的边地。」"
ts[17]['modern'] = "【边地胎生受乐问答】【义解】问：「那些胎生的人，住在七宝宫殿里，享受快乐吗？他们又忆念什么呢？」回答说：「经里比喻说：『譬如转轮圣王的王子，得罪了国王，被关在后官里，用金锁锁住，一切供具都不缺少，和转轮王一样。王子这时候虽然有各种好的娱乐器具，心里却不快乐，只想各种方法，求免罪出去。』那些胎生的人也是这样，虽然住在七宝宫殿里，有好的色、香、味、触，却不觉得快乐；"
ts[18]['modern'] = "【边地众生出离因缘与五智疑惑分科】【义解】只因为不见三宝，不能供养佛、修诸善本，把这个当作苦。认识到自己本来的罪业，深深自责忏悔，求离那个地方，就能够如愿，还和三辈往生的人一样，应当是五百年末才认识罪业忏悔罢了。」问：「以疑惑心往生安乐国，叫胎生，是怎么生起疑惑的呢？」回答说："
ts[19]['modern'] = "【五智总说与第一疑：疑念佛不必往生】【义解】经里只说「疑惑不信」，没有说出疑惑的意趣，探究不了知五智的文句，试着以对治的道理来说：不了佛智，就是不能信了佛的一切种智，因为不了知所以生起疑惑。这一句，是总辨所疑惑的内容；下面四句，一一对应对治所疑惑的内容。疑惑有四种意趣：第一，疑惑只凭忆念阿弥陀佛，不一定能往生安乐国。"
ts[20]['modern'] = "【第一疑的具体内容】【义解】为什么呢？经上说：『业道如同秤，重的先被牵走。』怎么能说一辈子或者百年、或者十年、或者一个月，无恶不造，只凭十念相续，就能往生，立刻入正定聚，毕竟不退转，和三途诸苦永远隔绝呢？如果是这样，重业先牵的义理，怎么让人相信呢？另外，旷劫以来都造作各种有漏行法，系属于三界，怎么能说不用断三界的结使烦恼，只凭短时间念阿弥陀佛，就能出离三界呢？系属三界的业力的义理，又怎么说呢？为了对治这个疑惑，所以说不思议智。"
ts[21]['modern'] = "【不思议智释义】【义解】不思议智，是说佛的智力能够以少作多，以多作少；以近为远，以远为近；以轻为重，以重为轻；以长为短，以短为长。像这样的佛智，无量、无边、不可思议。"
ts[22]['modern'] = "【不思议智喻：薪火喻、乘船喻】【义解】譬如一百个人、一百年积聚柴薪，堆得千仞高，一点点火焚烧，半天就烧尽了，怎么能说百年积聚的柴薪，半天烧不尽呢？又如瘸腿的人搭乘别人的船，借着风帆的势，一天就到千里之外，怎么能说瘸腿的人怎么能一天到千里呢？"
ts[23]['modern'] = "【不思议智喻：贡主喻、轮王喻】【义解】又如下贱的穷人得到一件祥瑞物品，把它贡给君主，君主庆贺得到宝物，给他重赏，顷刻之间富贵满溢，怎么能说有数十年做官辛勤备至、上下都不能通达的人，就说那种富贵是没有的事呢？又如劣夫凭自己的力量，连驴都骑不上去，跟着转轮王出行，就能乘虚空飞腾自在，又怎么能用连驴都骑不上的劣夫，说他一定不能乘空呢？"
ts[24]['modern'] = "【不思议智喻：断索喻、起死喻】【义解】又如十围粗的绳索，一千个人都拉不住，童子挥剑，瞬间就断成两截，怎么能说一个小孩的力量，不能断绳索呢？又如鸩鸟进入水里，鱼蚌都死了，犀角碰到泥里，死的都活过来，怎么能说性命一断，就没有复活的道理呢？又如黄鹄呼唤子安，子安就复活了，怎么能说坟下千年的骸骨，绝对没有复苏的道理呢？"
ts[25]['modern'] = "【自力他力与佛法不可思议】【义解】一切万法都有自力、他力，自摄、他摄，千开万闭，无量无边。怎么能用有障碍的识心，去怀疑那无障碍的佛法呢？另外，五种不思议中，佛法最不可思议。如果认为百年的恶业为重，怀疑十念念佛为轻，不能往生安乐国入正定聚，是不对的。"
ts[26]['modern'] = "【第二疑：疑佛智不玄绝】【义解】第二，疑惑佛的智慧对于人来说不是玄妙超绝的。为什么呢？因为一切名字都是相对待而生的，觉智是从不觉生的，就像辨不清方向是从记方向而生的。如果迷惑绝对不能破除，迷惑终究不能解；如果迷惑可以解开，那么迷惑的人能解，也可以说理悟的人会迷惑。迷和解、解和迷就像手翻覆一样，只是明和昧不同，又哪里能超然绝对呢？因为生起这个疑惑，所以对佛的智慧生疑不信。"
ts[27]['modern'] = "【对治第二疑：不可称智释义】【义解】为了对治这个疑惑，所以说不可称智。不可称智，是说佛智绝离称谓，不是相对待而有的。为什么这么说呢？法如果是有，就应该有知有的智慧；法如果是无，也应该有知无的智慧。诸法离于有、无两边，所以佛冥合诸法，智慧就绝离对待。"
ts[28]['modern'] = "【佛智离四句】【义解】你引用迷和悟作比喻，本身就是一种迷惑，不能成立迷解的道理。也像在梦里给别人解梦，虽然说是解梦，却不是不在梦中。用「知」去取佛，不叫知佛；用「不知」去取佛，也不是知佛；用「非知非不知」去取佛，也不是知佛；用「非非知非非不知」去取佛，也不是知佛。"
ts[29]['modern'] = "【佛智离言绝相】【义解】佛智离这四句，想要缘虑它的人，心念活动就止息；想要言说它的人，言语道就断灭。因为这个义理，《大智度论》说：「如果人见般若，这就是被缚；如果人不见般若，这也是被缚。如果人见般若，这就是解脱；如果人不见般若，这也是解脱。」这个偈子说，不离四句的就是被缚，离四句的就是解脱。你怀疑佛智和人智不玄妙超绝，是不对的。"
ts[30]['modern'] = "【第三疑：疑佛不能度一切众生】【义解】第三，怀疑佛实际上不能度脱一切众生。为什么呢？过去世有无量阿僧祇恒河沙数诸佛，现在十方世界也有无量无边阿僧祇恒河沙数诸佛，如果佛实际上能度一切众生，那么三界应该早就没有了，第二佛就不应该再为众生发菩提心，修行净土，摄受众生。而实际上有第二佛摄受众生，乃至实际上有三世十方无量诸佛摄受众生，所以知道佛实际上不能度一切众生。因为生起这个疑惑，所以对阿弥陀佛作有量想。"
ts[31]['modern'] = "【对治第三疑：大乘广智释义】【义解】为了对治这个疑惑，所以说大乘广智。大乘广智，是说佛没有一法不知，没有一烦恼不断，没有一善不具备，没有一众生不度。"
ts[32]['modern'] = "【大乘广智义一至三：诸佛相续度生】【义解】之所以有三世十方诸佛，有五个义理：第一，如果没有第二佛，乃至没有阿僧祇恒河沙数诸佛，佛就不能度一切众生。因为实际上能度一切众生，所以有十方无量诸佛，无量诸佛就是前佛所度化的众生。第二，如果一佛度尽一切众生，后面就不应该再有佛。为什么呢？因为没有觉他的义理了，又依什么义理说有三世佛呢？依觉他的义理，所以说诸佛都度一切众生。第三，后佛能度众生，也是前佛的能力，因为前佛度化才有后佛，就像帝王的铠甲，代代相承袭，后王就是前王的能力所成就的。"
ts[33]['modern'] = "【大乘广智义四：众生因缘不同】【义解】第四，佛力虽然能度一切众生，必须要有因缘，如果众生和前佛没有因缘，就需要后佛来度。这样没有因缘的众生，动辄经过百千万佛，都不闻不见佛，不是佛力微弱。譬如日月周行四天下，破除黑暗，但是盲人看不见，不是日月不明亮；雷震声音大得震耳，但是聋子听不见，不是声音不洪亮。觉了各种因缘道理才叫做佛。如果众生情执强，违背因缘道理，那不是佛的正觉不圆满。所以众生无量，佛也无量。如果追问佛不管有缘无缘，为什么不度尽一切众生，这是没道理的话。"
ts[34]['modern'] = "【大乘广智义五：众生非有边非无边，梦度喻】【义解】第五，众生如果度尽，世间就落入有边见了，因为这个义理，所以有无量佛，度一切众生。问：「如果众生不可度尽，世间就落入无边见，因为无边，佛就实际上不能度一切众生？」回答说：「世间非有边、非无边，也绝离四句。佛让众生离这四句，就叫做度。其实是非度、非不度，非尽、非不尽。譬如梦里渡大海，遇到涛波等灾难，那个人害怕叫出声来，外面的人把他叫醒，他就坦然无忧了，是渡了梦，不是渡了真实的河。」"
ts[35]['modern'] = "【度与不度：二悉檀义】【义解】问：「说渡和不渡都落入边见，为什么只说渡一切众生是大乘广智，不说不渡众生是大乘广智呢？」回答说：「众生没有不厌苦求乐、畏缚求解的，听到渡就归向，听到不渡不知道为什么不渡，就会说佛不是大慈悲，就不归向，不归向就长寝在轮回大梦里，没有办法醒过来。为了这类众生，多说渡，不说不渡。其次，《诸法无行经》也说：「佛不得佛道，也不度众生，凡夫强作分别，说佛度众生。」说「度众生」是对治悉檀，"
ts[36]['modern'] = "【二悉檀不相违，梦度答难】【义解】说「不度众生」是第一义悉檀，两种说法各有道理，不相违背。」问：「像梦被唤醒，难道不是度吗？如果一切众生的梦都息了，世间众生不就度尽了吗？」回答说：「说梦就是世间，如果梦息了，就没有做梦的人；如果没有做梦的人，也就没有说度的人。这样就知道世间就是出世间，虽然度无量众生，也不落入颠倒。」"
ts[37]['modern'] = "【第四疑：疑佛不得一切种智】【义解】第四，疑惑佛没有得到一切种智。为什么呢？如果能遍知一切法，诸法就落入有边；如果不能遍知，就不是一切种智。为了对治这个疑惑，所以说无等、无伦最上胜智。无等、无伦最上胜智：凡夫的智慧是虚妄的，佛的智慧是如实的，虚和实玄远差别，按理没有能相等的，所以说无等。"
ts[38]['modern'] = "【无等无伦最上胜智释义】【义解】声闻、辟支佛想要知道什么，要入定才能知道，出定就不知道，而且知见也有限；佛得到如实三昧，常在深定中，却能遍知照了万法，二与不二的深法，没有能和佛伦比的，所以说无伦。八地以上的菩萨，虽然得到报生三昧，作用没有出入，但是习气还微微熏染，三昧不是极其明净，和佛智相比，还是有上的。佛的智、断都圆满具足，如法而照，法无量所以照也无量，就像匣子大，盖子也大，所以说最上。"
ts[39]['modern'] = "【三句相成与第四疑非理】【义解】这三句也可以展转相成：因为佛智没有能相等的，所以没有能伦比的；因为没有能伦比的，所以是最上胜智；也可以因为是最上胜智，所以没有能相等的；因为没有能相等的，所以没有能伦比的。只说无等就够了，为什么还要下面两句呢？比如须陀洹的智慧，不能和阿罗汉相等，但还是同类；初地到十地菩萨也是这样，智慧虽然不等，但还是同类，为什么呢？因为不是最上的。你用「知有边」来问难，怀疑佛不是一切种智，是不对的。"
ts[40]['modern'] = "【十念相续问答开端】【义解】问：「下辈往生里说『十念相续，便得往生』，什么叫十念相续呢？」回答说：「譬如有人在空旷偏僻的地方，遇到怨贼，拔刀奋勇，直来想要杀他。这个人拼命跑，看见前面有一条河，如果能渡过河，性命就可以保全。这时候他只想着渡河的方法：『我到了河岸，是穿着衣服渡？还是脱了衣服渡？如果穿着衣服，恐怕渡不过去；"
ts[41]['modern'] = "【渡河喻明一念义，十念相续释名】【义解】如果脱衣服，恐怕来不及。』只想着渡河，没有别的念头，一个念头想着怎么渡河，就是一念。这样不夹杂别的心，就叫十念相续。修行的人也是这样，念阿弥陀佛，就像那个人念渡河一样，连续十念：或者念佛的名字，或者念佛的相好，或者念佛的光明，或者念佛的神力，或者念佛的功德，或者念佛的智慧，或者念佛的本愿。"
ts[42]['modern'] = "【十念功夫要点】【义解】没有别的心夹杂，心心相连续到十念，就叫十念相续。乍一听十念相续好像不难，但是凡夫的心如同野马，识念比猿猴还躁动，驰骋在六尘里，一刻也不停息。应当以至诚的心，预先自己克期练念，久了就积习成性，善根坚固。就如佛告诉频婆娑罗王说："
ts[43]['modern'] = "【善人生死念善喻】【义解】『人积累善行，死的时候没有恶念。就像树向西倾斜，倒下的时候一定向西弯。』如果到了刀风解体的时候，百苦凑身，如果平时的功夫不在怀，念佛怎么能辨明呢？"
ts[44]['modern'] = "【临终助念法】【义解】另外应当和志同道合的三五个人共结言约，临命终的时候，互相开导提醒，为对方称阿弥陀佛名号，愿生安乐，声声相次，成就十念。"
